const add = {                              // ESTree-style: plain objects, named children
  type: 'BinaryExpression', operator: '+',
  left:  { type: 'Literal', value: 1 },
  right: { type: 'Literal', value: 2 }
};
function print(node) {
  switch (node.type) {                                   // node-specific traversal
    case 'BinaryExpression': return `(${print(node.left)} ${node.operator} ${print(node.right)})`;
    case 'Literal': return String(node.value);
    default: throw new Error(`unhandled node type: ${node.type}`);
  }
}
